export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.61, 0.65, 0.97);
  scene.useRightHandedSystem = true;

  const camera = new BABYLON.ArcRotateCamera("camera", Math.PI / 2, Math.PI / 2.2, 2.5, new BABYLON.Vector3(0, 0, 0), scene);
  camera.attachControl(canvas, true);
  camera.inertia = 0.4;
  camera.lowerAlphaLimit = Math.PI / 2 - 0.4;
  camera.upperAlphaLimit = Math.PI / 2 + 0.4;
  camera.lowerBetaLimit = Math.PI / 3.2;
  camera.upperBetaLimit = Math.PI / 1.2;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.attachControl(canvas, true);

  new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);

  var f = new BABYLON.Vector4(0.5, 0, 1, 1); // front image = half the whole image along the width
  var b = new BABYLON.Vector4(0, 0, 0.5, 1); // back image = second half along the width
  const card = BABYLON.MeshBuilder.CreatePlane("card", { height: 1, width: 0.665, sideOrientation: BABYLON.Mesh.DOUBLESIDE }, scene);

  card.actionManager = new BABYLON.ActionManager(scene);

  let targetZIn = 0.3;
  let targetZOut = 0;
  let endFrame = 30;

  const ease = new BABYLON.CubicEase();
  ease.setEasingMode(BABYLON.EasingFunction.EASINGMODE_EASEINOUT);

  const animateZ = (targetZ) => {
    const anim = new BABYLON.Animation(
      "zMove",
      "position.z",
      60,
      BABYLON.Animation.ANIMATIONTYPE_FLOAT,
      BABYLON.Animation.ANIMATIONLOOPMODE_CONSTANT
    );
    anim.setKeys([
      { frame: 0, value: card.position.z },
      { frame: endFrame, value: targetZ },
    ]);
    anim.setEasingFunction(ease);
    card.animations = [anim];
    scene.beginAnimation(card, 0, endFrame, false);
  };

  card.actionManager.registerAction(
    new BABYLON.ExecuteCodeAction(BABYLON.ActionManager.OnPointerOverTrigger, () => {
      isHover = true;

      if (Math.abs(card.position.z - targetZIn) > 0.001) {
        animateZ(targetZIn);
      }
    })
  );

  card.actionManager.registerAction(
    new BABYLON.ExecuteCodeAction(BABYLON.ActionManager.OnPointerOutTrigger, () => {
      isHover = false;

      if (Math.abs(card.position.z - targetZOut) > 0.001) {
        animateZ(targetZOut);
      }
    })
  );

  let isHover = false;
  let hoverTargetRotationX = 0;
  let hoverTargetRotationY = 0;

  scene.onBeforeRenderObservable.add(() => {
    if (isHover) {
      const pick = scene.pick(scene.pointerX, scene.pointerY, (mesh) => mesh === card);
      if (pick?.hit && pick.getTextureCoordinates()) {
        const uv = pick.getTextureCoordinates();

        const offsetX = uv.x - 0.5; // 좌우 → Y회전
        const offsetY = uv.y - 0.5; // 상하 → X회전

        hoverTargetRotationY = BABYLON.Scalar.Clamp(offsetX * 0.6, -0.2, 0.2);
        hoverTargetRotationX = BABYLON.Scalar.Clamp(-offsetY * 0.6, -0.2, 0.2);
      }
    } else {
      hoverTargetRotationX = 0;
      hoverTargetRotationY = 0;
    }

    card.rotation.y = BABYLON.Scalar.Lerp(card.rotation.y, hoverTargetRotationY, 0.2);
    card.rotation.x = BABYLON.Scalar.Lerp(card.rotation.x, hoverTargetRotationX + Math.PI, 0.2); // 기본 x = π 보정 포함
  });

  var texture = new BABYLON.DynamicTexture("dynamic texture", { width: 512, height: 512 }, scene, true);
  var material = new BABYLON.PBRMaterial("mat", scene);
  material.albedoTexture = texture;
  material.metallic = 0;
  material.roughness = 1;
  card.material = material;

  var context = texture.getContext();
  var backgroundImage = new Image();
  backgroundImage.crossOrigin = "anonymous";

  var proxyUrl = "https://api.allorigins.win/raw?url=";
  var testUrl = "https://i.pinimg.com/736x/c9/45/35/c945358ed1c412dfc195579d228735b7.jpg";

  const getBase64FromUrl = async (url) => {
    const data = await fetch(proxyUrl + encodeURIComponent(url));
    const blob = await data.blob();
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.readAsDataURL(blob);
      reader.onloadend = function () {
        resolve(reader.result);
      };
    });
  };

  getBase64FromUrl(testUrl).then((a) => {
    backgroundImage.src = a;
  });

  backgroundImage.onload = function () {
    context.clearRect(0, 0, 512, 512);
    context.save();
    context.translate(0, 512);
    context.scale(1, -1);
    context.drawImage(backgroundImage, 0, 0, 512, 512);
    context.restore();

    texture.update();
  };

  const shaderMaterial = new BABYLON.ShaderMaterial(
    "shader",
    scene,
    {
      vertex: "custom",
      fragment: "custom",
    },
    {
      attributes: ["position", "uv", "normal"],
      uniforms: ["worldViewProjection", "viewAngle", "hover"],
      samplers: ["textureSampler"],
    }
  );

  shaderMaterial.setTexture("textureSampler", texture);
  shaderMaterial.setFloat("hover", 0.0);
  shaderMaterial.setFloat("viewAngle", 0.0);
  card.material = shaderMaterial;

  BABYLON.Effect.ShadersStore["customVertexShader"] = `
        precision highp float;
        attribute vec3 position;
        attribute vec2 uv;
        uniform mat4 worldViewProjection;
        varying vec2 vUV;
        void main(void) {
            gl_Position = worldViewProjection * vec4(position, 1.0);
            vUV = uv;
        }
    `;

  BABYLON.Effect.ShadersStore["customFragmentShader"] = `
        precision highp float;
        uniform float viewAngle;
        uniform float hover;
        uniform sampler2D textureSampler;
        varying vec2 vUV;

        float holoBand(vec2 uv, float offset, float spacing, float thickness) {
            // float wave = sin((uv.x + uv.y + offset) * spacing + sin(uv.y * 4.0));
            // float wave = sin((uv.x + uv.y) * 30.0 + offset * 10.0 + sin(uv.y * 10.0) * 0.5);
            float wave = sin((uv.x + uv.y + offset) * spacing + sin(uv.y * 4.0) * 0.2);

            float band = smoothstep(0.0, 1.0, 1.0 - abs(wave));
            return pow(band, thickness);
        }

        void main(void) {
            vec3 base = texture2D(textureSampler, vUV).rgb;
            vec3 holo = vec3(0.0);

            if (hover > 0.5) {
                float shift = viewAngle * 1.2;

                float b = holoBand(vUV, shift, 6.0, 1.5); // spacing 감소 → fewer bands, pow 낮춤 → thick

                vec3 rainbow = vec3(
                    sin((vUV.x + shift) * 10.0) * 0.5 + 0.5,
                    sin((vUV.y + shift + 1.0) * 10.0) * 0.5 + 0.5,
                    sin((vUV.x + vUV.y + shift + 2.0) * 10.0) * 0.5 + 0.5
                );

                holo = rainbow * b * 0.6;
                holo = pow(holo, vec3(1.4));
            }

            gl_FragColor = vec4(base + holo, 1.0);
        }
    `;

  scene.onPointerObservable.add((pointerInfo) => {
    if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERMOVE) {
      const pick = scene.pick(scene.pointerX, scene.pointerY, (mesh) => mesh === card);
      shaderMaterial.setFloat("hover", pick?.hit ? 1.0 : 0.0);
    }
  });

  let cameraDir;
  let cardForward;
  let viewAngle;

  scene.registerBeforeRender(() => {
    cameraDir = camera.position.subtract(card.position).normalize();
    cardForward = BABYLON.Vector3.TransformNormal(BABYLON.Axis.Z.negate(), card.getWorldMatrix());
    viewAngle = BABYLON.Vector3.Dot(cameraDir, cardForward);

    if (!shaderMaterial) {
      console.warn("shaderMaterial not ready");
      return;
    }

    shaderMaterial.setFloat("viewAngle", viewAngle);
  });

  return scene;
}
